let studio={type:'quote',id:'',projectId:''};
function quoteFor(pid){return commercial.quotes.filter(q=>q.projectId===pid).sort((a,b)=>(b.revision||1)-(a.revision||1))[0]||null}
function contractFor(pid){return commercial.contracts.find(c=>c.projectId===pid&&c.status!=='closed')||commercial.contracts.find(c=>c.projectId===pid)||null}
function sumLines(lines){return (lines||[]).filter(x=>x.included!==false).reduce((a,l)=>a+(+l.qty||0)*(+l.unitPrice||0)*(1-(+l.discount||0)/100),0)}
function quoteTotal(q){let net=sumLines(q?.lines||[]),tax=q?.vatEnabled?net*(+q.vatRate||0)/100:0;return{net,tax,total:net+tax}}
function contractTotal(c){return sumLines(c?.lines||[])}
function contractValue(pid){let c=contractFor(pid);return c?contractTotal(c):(quoteFor(pid)?quoteTotal(quoteFor(pid)).total:(data.find(p=>p.id===pid)?.value||0))}
function scheduleSum(c){return (c?.schedule||[]).reduce((a,x)=>a+(+x.percent||0),0)}
function nextBillable(p){let c=contractFor(p.id);if(!c||c.status!=='active')return 0;let total=contractTotal(c),row=(c.schedule||[]).find(x=>(+x.claimed||0)<total*(+x.percent||0)/100-0.5);if(!row)return Math.max(0,total-(+p.invoice||0));let due=total*(+row.percent||0)/100;return Math.max(0,due-(+row.claimed||0))}
function syncProjectCommercial(pid){let p=data.find(x=>x.id===pid),c=contractFor(pid);if(p&&c&&c.status==='active')p.value=contractTotal(c)}
