const PRIORITIES=['Urgent','High','Normal','Low'];function priorityRank(x){return({Urgent:4,High:3,Normal:2,Low:1})[x]||2}function priorityBadge(x){x=x||'Normal';return '<span class="prio prio-'+x+'">'+x+'</span>'}function canEditProjectPriority(p){let r=U(currentUser).role;return r==='Owner'||(r==='Project Manager'&&p.pm===currentUser)||(r==='Project Engineer'&&p.projectEngineer===currentUser)}function priorityControl(p){if(!canEditProjectPriority(p))return priorityBadge(p.priority);return '<select data-priority="'+p.id+'" class="btn small">'+PRIORITIES.map(v=>'<option '+(v===p.priority?'selected':'')+'>'+v+'</option>').join('')+'</select>'}
function canSee(p){let r=U(currentUser).role;if(r==='Owner')return true;if(r==='Accountant')return p.stage>=4;if(r==='Checker')return Number(p.stage)<=3||p.checker===currentUser||p.finalTechnicalApproved===true;if(r==='Project Manager')return p.pm===currentUser;if(r==='Project Engineer')return p.projectEngineer===currentUser||p.tasks.some(t=>t.assignee===currentUser);return p.tasks.some(t=>t.assignee===currentUser)}
