function ownerName(p){let s=p.stage;if(s<=1)return U(p.pm).name;if(s===2){let open=p.tasks.find(t=>t.status!=='confirmed');return open?U(open.assignee).name:'Engineering Team'}if(s===3)return U(p.checker).name;if(s>=4&&s<=5)return U('accountant').name;return '—'}
