function actionButtons(p){let role=U(currentUser).role;if(p.stage===0&&['Owner','Project Manager','Project Engineer'].includes(role))return '<button class="btn primary" data-next="'+p.id+'">اعتماد Scope → توزيع Tasks</button>';if(p.stage===1&&['Owner','Project Manager','Project Engineer'].includes(role))return '<button class="btn primary" data-start="'+p.id+'">بدء التنفيذ</button>';if(p.stage===2&&['Owner','Project Manager','Project Engineer'].includes(role))return '<button class="btn primary" data-engc="'+p.id+'">Send to Engineering Confirm</button>';if(p.stage===3&&['Owner','Checker','Project Manager'].includes(role))return '<button class="btn green" data-next="'+p.id+'">Confirm → Accountant</button>';if(p.stage===4&&['Owner','Accountant'].includes(role))return '<button class="btn gold" data-claim="'+p.id+'">Issue Claim</button>';if(p.stage===5&&['Owner','Accountant'].includes(role))return '<button class="btn green" data-pay="'+p.id+'">Receive Payment</button>';if(p.stage===6)return '<span class="badge green">FINANCIALLY CLOSED ✓</span>';return '<span class="muted">لا يوجد إجراء متاح لك الآن</span>'}
function inbox(){let out=[];visible().forEach(p=>{let role=U(currentUser).role;if(role==='Engineer')p.tasks.filter(t=>t.assignee===currentUser&&t.status!=='confirmed').forEach(t=>out.push({p,text:t.status==='submitted'?'بانتظار المراجعة: '+t.name:'أكمل '+t.name,prio:t.priority}));if(role==='Checker'&&p.stage===3)out.push({p,text:'راجع واعتمد Engineering Package',prio:p.priority||'High'});if(role==='Accountant'&&p.stage===4)out.push({p,text:'جاهز للتواصل مع العميل وإصدار المطالبة / الفاتورة',prio:p.billingPriority||p.priority||'High'});if(role==='Accountant'&&p.stage===5)out.push({p,text:'تابع التحصيل — متبقي '+money(p.invoice-p.paid),prio:p.billingPriority||'Urgent'});if(role==='Project Manager'&&p.stage<=2)out.push({p,text:required(p),prio:p.priority||'High'});if(role==='Project Engineer'&&p.projectEngineer===currentUser&&p.stage<=2)out.push({p,text:required(p),prio:p.priority||'High'});if(role==='Owner'&&p.stage===4)out.push({p,text:'دخل الحسابات — تواصل مع العميل / تابع المطالبة',prio:p.billingPriority||p.priority||'High'});if(role==='Owner'&&p.stage<6&&parseInt(p.since)>=5)out.push({p,text:'مشروع متوقف منذ '+p.since,prio:'Urgent'})});return out}
