let active=list.filter(x=>x.stage<6).length,eng=list.filter(x=>x.stage<=3).length,bill=list.filter(x=>x.stage===4).length,collect=list.filter(x=>x.stage===5).length,out=list.reduce((s,x)=>s+Math.max(0,x.invoice-x.paid),0),ib=inbox();$('inboxCount').textContent=ib.length;
$('kpis').innerHTML=[['مشاريع ظاهرة لك',list.length],['نشطة',active],['هندسة',eng],['جاهز للمطالبة',bill],['تحصيل',collect],['Outstanding',money(out)]].map(z=>'<div class="kpi"><small>'+z[0]+'</small><b>'+z[1]+'</b></div>').join('');
if(!list.some(x=>x.id===sel))sel=list[0]?.id||'';let q=project();if(!q){$('flow').innerHTML=$('dashProjects').innerHTML=$('timeline').innerHTML=$('control').innerHTML='<div class="empty">لا توجد مشاريع متاحة لهذا المستخدم.</div>'}else{$('flow').innerHTML=ST.map((z,i)=>'<div class="stage '+(i<q.stage?'done':i===q.stage?'active':'')+'"><i>'+(i+1)+'</i><b>'+z[0]+'</b><div class="muted">'+z[1]+'</div></div>').join('');$('dashProjects').innerHTML=rows(false);$('projectsTable').innerHTML=rows(true);$('timeline').innerHTML=q.events.slice(0,7).map(x=>'<div class="event"><b>'+x.text+'</b><p>'+U(x.user).name+' • '+x.at+'</p></div>').join('');$('control').innerHTML=projectCenter(q)}
