function projectCenter(q){let conf=q.tasks.filter(t=>t.status==='confirmed').length,prog=q.tasks.length?Math.round(q.tasks.reduce((s,t)=>s+t.progress,0)/q.tasks.length):0;return '<div class="top"><div><h2 style="margin:0">'+q.id+' — '+q.name+'</h2><div class="muted">'+q.client+' • Contract '+money(q.value)+'</div></div><div>'+stageBadge(q.stage)+' &nbsp; '+priorityControl(q)+'</div></div><div class="control"><div><small>Project Priority</small><b>'+priorityBadge(q.priority)+'</b></div><div><small>Current Owner</small><b>'+ownerName(q)+'</b></div><div><small>Required Action</small><b>'+required(q)+'</b></div><div><small>Waiting Since</small><b>'+q.since+'</b></div></div>'+(q.stage>=4&&q.stage<6?'<div class="handover"><b>✓ Engineering → Accounts Handover</b><div class="muted">المشروع دخل الحسابات. أولوية التواصل مع العميل: '+priorityBadge(q.billingPriority||q.priority)+' • '+(q.accountsEnteredAt?'من '+q.accountsEnteredAt:'جاهز الآن')+'</div></div>':'')+'<div class="projecttabs"><button class="pt active" data-pt="overview">Overview</button><button class="pt" data-pt="ptasks">Tasks</button><button class="pt" data-pt="pcommercial">Commercial</button><button class="pt" data-pt="pfin">Accounts</button><button class="pt" data-pt="ptime">Timesheet</button><button class="pt" data-pt="pdocs">Documents</button><button class="pt" data-pt="pactivity">Activity</button></div><div id="ptbody">'+ptBody(q,'overview',conf,prog)+'</div><div class="actions" style="margin-top:12px">'+actionButtons(q)+'</div>'}
function ptBody(q,tab,conf,prog){if(tab==='overview')return '<div class="miniGrid"><div><small>Project Manager</small><b>'+U(q.pm).name+'</b></div><div><small>Project Engineer</small><b>'+U(q.projectEngineer).name+'</b></div><div><small>Checker</small><b>'+U(q.checker).name+'</b></div><div><small>Engineering Progress</small><b>'+prog+'%</b><div class="progress"><i style="width:'+prog+'%"></i></div></div><div><small>Tasks Confirmed</small><b>'+conf+'/'+q.tasks.length+'</b></div><div><small>Billing Status</small><b>'+money(q.invoice)+'</b></div><div><small>Outstanding</small><b>'+money(Math.max(0,q.invoice-q.paid))+'</b></div><div><small>Approved Labor Hours</small><b>'+projectHours(q.id).toFixed(2)+' h</b></div><div><small>Known approved labor cost</small><b>'+money(projectLaborCost(q.id))+'</b></div></div>';if(tab==='ptasks')return '<table class="table"><tr><th>Task</th><th>Engineer</th><th>Due</th><th>Priority</th><th>Progress</th><th>Status</th></tr>'+q.tasks.map(t=>'<tr><td>'+t.name+'</td><td>'+U(t.assignee).name+'</td><td>'+t.due+'</td><td>'+t.priority+'</td><td>'+t.progress+'%</td><td>'+taskBadge(t.status)+'</td></tr>').join('')+'</table>';if(tab==='pcommercial')return projectCommercialHTML(q.id);if(tab==='pfin')return '<div class="miniGrid"><div><small>Quotation</small><b>'+(quoteFor(q.id)?.number||'—')+'</b></div><div><small>Contract</small><b>'+(contractFor(q.id)?.number||'—')+'</b></div><div><small>Contract Value</small><b>'+money(contractValue(q.id))+'</b></div><div><small>Claimed</small><b>'+money(q.invoice)+'</b></div><div><small>Paid</small><b>'+money(q.paid)+'</b></div><div><small>Retention</small><b>'+money(q.retention)+'</b></div><div><small>Outstanding</small><b>'+money(Math.max(0,q.invoice-q.paid))+'</b></div><div><small>Approved Labor Hours</small><b>'+projectHours(q.id).toFixed(2)+' h</b></div><div><small>Known approved labor cost</small><b>'+money(projectLaborCost(q.id))+'</b></div></div>';if(tab==='ptime')return projectTimesheetHTML(q.id);if(tab==='pdocs')return '<div class="empty">Documents registered: <b>'+q.docs+'</b><br><span class="muted">المرحلة القادمة سنربط Drawings / Contracts / Claims / Transmittals فعليًا.</span></div>';return q.events.map(x=>'<div class="event"><b>'+x.text+'</b><p>'+U(x.user).name+' • '+x.at+'</p></div>').join('')}
function projectHours(pid){return timesheets.filter(t=>t.projectId===pid&&t.status==='approved').reduce((a,t)=>a+Number(t.approvedHours??t.hours??0),0)}
function projectLaborCost(pid){return timesheets.filter(t=>t.projectId===pid&&t.status==='approved'&&t.costSnapshot).reduce((a,t)=>a+Number(t.costSnapshot.amountEGP||0),0)}
