function projectTimesheetHTML(pid){let r=U(currentUser).role,rows=timesheets.filter(t=>t.projectId===pid&&tsVisible(t));if(!rows.length)return '<div class="empty">لا يوجد Timesheet لهذا المشروع.</div>';return '<table class="table"><tr><th>Date</th><th>Employee</th><th>Task</th><th>Hours</th><th>Status</th>'+(r==='Owner'||r==='Accountant'?'<th>Hourly Cost</th><th>Known approved labor cost</th>':'')+'</tr>'+rows.map(t=>'<tr><td>'+t.date+'</td><td>'+U(t.user).name+'</td><td>'+taskName(t.projectId,t.taskId)+'</td><td>'+Number(t.hours).toFixed(2)+'</td><td>'+tsBadge(t.status)+'</td>'+(r==='Owner'||r==='Accountant'?'<td>'+money(U(t.user).rate)+'/h</td><td>'+(t.status==='approved'&&t.costSnapshot?money(t.costSnapshot.amountEGP):'غير مثبت / Unpriced')+'</td>':'')+'</tr>').join('')+'</table>'}
function taskName(pid,tid){let p=data.find(x=>x.id===pid),t=p?.tasks.find(x=>x.id===tid);return t?.name||tid||'General'}
function tsBadge(s){return '<span class="badge '+(s==='approved'?'green':s==='rejected'?'red':'orange')+'">'+s.toUpperCase()+'</span>'}
function renderTimesheets(){let r=U(currentUser).role,rows=timesheets.filter(tsVisible),approved=rows.filter(t=>t.status==='approved'),hours=approved.reduce((a,t)=>a+(+(t.approvedHours??t.hours)||0),0),pending=rows.filter(t=>t.status==='pending').length,cost=approved.reduce((a,t)=>a+(t.costSnapshot?.amountEGP||0),0);$('tsKpis').innerHTML=[['Approved Hours',hours.toFixed(2)],['Pending Entries',pending],['Projects',new Set(rows.map(t=>t.projectId)).size],['Known approved labor cost',(r==='Owner'||r==='Accountant')?money(cost):'Hidden']].map(x=>'<div class="kpi"><small>'+x[0]+'</small><b>'+x[1]+'</b></div>').join('');$('tsTable').innerHTML=rows.length?'<table class="table"><tr><th>Date</th><th>Employee</th><th>Project</th><th>Task</th><th>Hours</th><th>Note</th><th>Status</th>'+(r==='Owner'||r==='Accountant'?'<th>Cost</th>':'')+'<th>Action</th></tr>'+rows.map(t=>'<tr><td>'+t.date+'</td><td>'+U(t.user).name+'</td><td>'+t.projectId+'</td><td>'+taskName(t.projectId,t.taskId)+'</td><td>'+Number(t.hours).toFixed(2)+'</td><td>'+t.note+'</td><td>'+tsBadge(t.status)+'</td>'+(r==='Owner'||r==='Accountant'?'<td class="cost">'+(t.status==='approved'&&t.costSnapshot?money(t.costSnapshot.amountEGP):'غير مثبت / Unpriced')+'</td>':'')+'<td>'+tsActions(t)+'</td></tr>').join('')+'</table>':'<div class="empty">لا يوجد Timesheet.</div>'}
function tsActions(t){let r=U(currentUser).role;if(t.status==='pending'&&['Owner','Project Manager'].includes(r))return '<button class="btn small green" data-tsapprove="'+t.id+'">Approve</button> <button class="btn small red" data-tsreject="'+t.id+'">Reject</button>';if(t.status==='rejected'&&t.user===currentUser)return '<button class="btn small" data-tsresubmit="'+t.id+'">Resubmit</button>';return '—'}

