function projectCommercialHTML(pid){let q=quoteFor(pid),c=contractFor(pid),p=data.find(x=>x.id===pid),cv=contractValue(pid);return '<div class="commercialGrid"><div><small>Quotation</small><b>'+(q?q.number+' · R'+q.revision:'Not created')+'</b><div>'+statusCommercial(q?.status||'none')+'</div></div><div><small>Contract</small><b>'+(c?c.number:'Not created')+'</b><div>'+statusCommercial(c?.status||'none')+'</div></div><div><small>Commercial Value</small><b>'+money(cv)+'</b></div><div><small>Next Billable</small><b>'+money(nextBillable(p))+'</b></div></div><div class="actions" style="margin-top:10px"><button class="btn" data-openquote="'+pid+'">'+(q?'Open Quotation Studio':'Create Quotation')+'</button>'+(q&&q.status==='approved'?'<button class="btn gold" data-opencontract="'+pid+'">'+(c?'Open Contract Studio':'Create Contract')+'</button>':'')+'</div>'+(c?'<div style="margin-top:12px"><b>Payment Schedule</b>'+scheduleHTML(c)+'</div>':'')}
function statusCommercial(s){return '<span class="commercialStatus '+s+'">'+String(s||'—').replace('_',' ').toUpperCase()+'</span>'}
