function renderCommercial(){if(!$('commercialTable'))return;let list=visible();$('commercialKpis').innerHTML=[['Projects',list.length],['Approved Quotes',list.filter(p=>quoteFor(p.id)?.status==='approved').length],['Active Contracts',list.filter(p=>contractFor(p.id)?.status==='active').length],['Contract Value',money(list.reduce((a,p)=>a+contractValue(p.id),0))],['Claimed',money(list.reduce((a,p)=>a+(+p.invoice||0),0))],['Outstanding',money(list.reduce((a,p)=>a+Math.max(0,(+p.invoice||0)-(+p.paid||0)),0))]].map(x=>'<div class="kpi"><small>'+x[0]+'</small><b>'+x[1]+'</b></div>').join('');$('commercialTable').innerHTML='<table class="table"><tr><th>Project</th><th>Quotation</th><th>Quote Status</th><th>Contract</th><th>Contract Status</th><th>Value</th><th>Actions</th></tr>'+list.map(p=>{let q=quoteFor(p.id),c=contractFor(p.id);return '<tr><td><b>'+p.id+'</b><br><span class="muted">'+p.name+'</span></td><td>'+(q?q.number+' R'+q.revision:'—')+'</td><td>'+statusCommercial(q?.status||'none')+'</td><td>'+(c?c.number:'—')+'</td><td>'+statusCommercial(c?.status||'none')+'</td><td>'+money(contractValue(p.id))+'</td><td><button class="btn small" data-openquote="'+p.id+'">'+(q?'Quotation':'Create Quote')+'</button> '+(q&&q.status==='approved'?'<button class="btn small gold" data-opencontract="'+p.id+'">'+(c?'Contract':'Create Contract')+'</button>':'')+'</td></tr>'}).join('')+'</table>'}
function newQuote(pid){let p=data.find(x=>x.id===pid),nums=commercial.quotes.map(q=>parseInt((q.number.match(/Q-(\\d+)/)||[])[1]||0)),n=Math.max(100,...nums)+1;return{id:'Q-'+Date.now(),number:'RNX-Q-'+n+'/2026',revision:1,projectId:pid,client:p?.client||'',date:new Date().toISOString().slice(0,10),validity:5,currency:'EGP',language:'bilingual',vatEnabled:false,vatRate:14,status:'draft',terms:'50% Advance Payment upon contract award.\\n50% upon submission of final approved engineering package.',exclusions:'Engineering stamp and authority approvals are excluded.\\nPrices exclude VAT unless otherwise stated.',notes:'',lines:[{id:'L1',included:true,description:'Steel Detailing & Shop Drawings',qty:1,unit:'L.S',unitPrice:p?.value||0,discount:0}]}}
function newContractFromQuote(q){let nums=commercial.contracts.map(c=>parseInt((c.number.match(/C-(\\d+)/)||[])[1]||0)),n=Math.max(100,...nums)+1;return{id:'C-'+Date.now(),number:'RNX-C-'+n+'/2026',projectId:q.projectId,quoteId:q.id,client:q.client,status:'draft',contractDate:new Date().toISOString().slice(0,10),startDate:'',durationDays:10,currency:q.currency||'EGP',scope:(q.lines||[]).filter(l=>l.included!==false).map(l=>l.description).join(' + '),terms:q.terms||'',exclusions:q.exclusions||'',lines:(q.lines||[]).filter(l=>l.included!==false).map(l=>({description:l.description,qty:l.qty,unit:l.unit,unitPrice:l.unitPrice,discount:l.discount||0})),schedule:[{id:'P1',label:'Advance Payment / دفعة مقدمة',percent:50,trigger:'Contract Award',claimed:0},{id:'P2',label:'Final Submission / التسليم النهائي',percent:50,trigger:'Engineering Confirm',claimed:0}]}}

