function openQuoteStudio(pid){let q=quoteFor(pid);if(!q){q=newQuote(pid);commercial.quotes.push(q)}studio={type:'quote',id:q.id,projectId:pid};$('commercialStudio').classList.add('show');renderStudio()}
function openContractStudio(pid){let c=contractFor(pid);if(!c){let q=quoteFor(pid);if(!q||q.status!=='approved')return toast('اعتمد عرض السعر أولًا');c=newContractFromQuote(q);commercial.contracts.push(c)}studio={type:'contract',id:c.id,projectId:pid};$('commercialStudio').classList.add('show');renderStudio()}
function renderStudio(){let isQ=studio.type==='quote',o=isQ?commercial.quotes.find(x=>x.id===studio.id):commercial.contracts.find(x=>x.id===studio.id),p=data.find(x=>x.id===studio.projectId);$('studioTitle').textContent=isQ?'RONIX Executive Quotation Studio':'RONIX Contract Studio';$('studioSub').textContent=(p?.id||'')+' — '+(p?.name||'');$('studioSave').style.display='';$('studioApprove').style.display='';$('studioConvert').style.display=isQ&&o.status==='approved'?'':'none';$('studioApprove').textContent=isQ?(o.status==='approved'?'Approved ✓':'Approve Quotation'):(o.status==='active'?'Active ✓':o.status==='approved'?'Sign & Activate':'Approve Contract');$('studioEditor').innerHTML=isQ?quoteEditor(o,p):contractEditor(o,p);wireStudio();renderStudioPreview()}
function quoteEditor(q,p){return '<div class="studioGrid"><div class="studioField"><label>Quotation No.</label><input data-q="number" value="'+escv(q.number)+'"></div><div class="studioField"><label>Revision</label><input data-q="revision" type="number" min="1" value="'+q.revision+'"></div><div class="studioField"><label>Client</label><input data-q="client" value="'+escv(q.client)+'"></div><div class="studioField"><label>Project</label><input value="'+escv(p?.name||'')+'" disabled></div><div class="studioField"><label>Date</label><input data-q="date" type="date" value="'+q.date+'"></div><div class="studioField"><label>Validity (days)</label><input data-q="validity" type="number" value="'+q.validity+'"></div><div class="studioField"><label>Language</label><select data-q="language"><option value="bilingual" '+(q.language==='bilingual'?'selected':'')+'>Arabic + English</option><option value="ar" '+(q.language==='ar'?'selected':'')+'>Arabic</option><option value="en" '+(q.language==='en'?'selected':'')+'>English</option></select></div><div class="studioField"><label>Currency</label><select data-q="currency"><option>EGP</option><option>SAR</option><option>USD</option><option>AED</option></select></div><div class="studioFull"><b>Scope & Pricing</b><table class="lineEditor"><tr><th>✓</th><th>Description</th><th>Qty</th><th>Unit</th><th>Unit Price</th><th>Disc %</th></tr>'+(q.lines||[]).map((l,i)=>'<tr><td><input data-line="included:'+i+'" type="checkbox" '+(l.included!==false?'checked':'')+'></td><td><input data-line="description:'+i+'" value="'+escv(l.description)+'"></td><td><input data-line="qty:'+i+'" type="number" value="'+l.qty+'"></td><td><input data-line="unit:'+i+'" value="'+escv(l.unit)+'"></td><td><input data-line="unitPrice:'+i+'" type="number" value="'+l.unitPrice+'"></td><td><input data-line="discount:'+i+'" type="number" value="'+(l.discount||0)+'"></td></tr>').join('')+'</table><button class="btn small" id="addQuoteLine">+ Add Line</button></div><div class="studioField"><label>VAT</label><select data-q="vatEnabled"><option value="false" '+(!q.vatEnabled?'selected':'')+'>Excluded</option><option value="true" '+(q.vatEnabled?'selected':'')+'>Add VAT</option></select></div><div class="studioField"><label>VAT Rate %</label><input data-q="vatRate" type="number" value="'+q.vatRate+'"></div><div class="studioField studioFull"><label>Payment Terms</label><textarea data-q="terms">'+escv(q.terms)+'</textarea></div><div class="studioField studioFull"><label>Exclusions</label><textarea data-q="exclusions">'+escv(q.exclusions)+'</textarea></div><div class="studioField studioFull"><label>Notes</label><textarea data-q="notes">'+escv(q.notes||'')+'</textarea></div></div>'}
function contractEditor(c,p){let sum=scheduleSum(c);return '<div class="studioGrid"><div class="studioField"><label>Contract No.</label><input data-c="number" value="'+escv(c.number)+'"></div><div class="studioField"><label>Status</label><input value="'+c.status+'" disabled></div><div class="studioField"><label>Client</label><input data-c="client" value="'+escv(c.client)+'"></div><div class="studioField"><label>Project</label><input value="'+escv(p?.name||'')+'" disabled></div><div class="studioField"><label>Contract Date</label><input data-c="contractDate" type="date" value="'+c.contractDate+'"></div><div class="studioField"><label>Start Date</label><input data-c="startDate" type="date" value="'+(c.startDate||'')+'"></div><div class="studioField"><label>Duration (working days)</label><input data-c="durationDays" type="number" value="'+c.durationDays+'"></div><div class="studioField"><label>Contract Value</label><input value="'+contractTotal(c)+'" disabled></div><div class="studioField studioFull"><label>Scope of Work</label><textarea data-c="scope">'+escv(c.scope||'')+'</textarea></div><div class="studioFull"><b>Payment Schedule <span class="'+(Math.abs(sum-100)<.01?'scheduleGood':'scheduleBad')+'">('+sum.toFixed(2)+'%)</span></b><table class="lineEditor"><tr><th>Milestone</th><th>Trigger</th><th>%</th></tr>'+(c.schedule||[]).map((r,i)=>'<tr><td><input data-sch="label:'+i+'" value="'+escv(r.label)+'"></td><td><input data-sch="trigger:'+i+'" value="'+escv(r.trigger)+'"></td><td><input data-sch="percent:'+i+'" type="number" step="0.01" value="'+r.percent+'"></td></tr>').join('')+'</table><button class="btn small" id="addSchedule">+ Add Payment</button></div><div class="studioField studioFull"><label>Commercial / Sensitive Terms</label><textarea data-c="terms">'+escv(c.terms||'')+'</textarea></div><div class="studioField studioFull"><label>Exclusions</label><textarea data-c="exclusions">'+escv(c.exclusions||'')+'</textarea></div></div>'}
function escv(x){return String(x??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;')}
function wireStudio(){document.querySelectorAll('[data-q]').forEach(e=>e.oninput=e.onchange=()=>{let q=commercial.quotes.find(x=>x.id===studio.id),k=e.dataset.q,v=e.type==='number'?+e.value:e.value;if(k==='vatEnabled')v=e.value==='true';q[k]=v;renderStudioPreview()});document.querySelectorAll('[data-line]').forEach(e=>e.oninput=e.onchange=()=>{let q=commercial.quotes.find(x=>x.id===studio.id),[k,i]=e.dataset.line.split(':'),v=e.type==='checkbox'?e.checked:e.type==='number'?+e.value:e.value;q.lines[+i][k]=v;renderStudioPreview()});document.querySelectorAll('[data-c]').forEach(e=>e.oninput=e.onchange=()=>{let c=commercial.contracts.find(x=>x.id===studio.id),k=e.dataset.c;c[k]=e.type==='number'?+e.value:e.value;syncProjectCommercial(c.projectId);renderStudioPreview()});document.querySelectorAll('[data-sch]').forEach(e=>e.oninput=e.onchange=()=>{let c=commercial.contracts.find(x=>x.id===studio.id),[k,i]=e.dataset.sch.split(':');c.schedule[+i][k]=e.type==='number'?+e.value:e.value;renderStudioPreview()});let a=$('addQuoteLine');if(a)a.onclick=()=>{commercial.quotes.find(x=>x.id===studio.id).lines.push({id:'L'+Date.now(),included:true,description:'New Service',qty:1,unit:'L.S',unitPrice:0,discount:0});renderStudio()};let b=$('addSchedule');if(b)b.onclick=()=>{commercial.contracts.find(x=>x.id===studio.id).schedule.push({id:'P'+Date.now(),label:'New Payment',trigger:'Milestone',percent:0,claimed:0});renderStudio()}}
function renderStudioPreview(){let isQ=studio.type==='quote',o=isQ?commercial.quotes.find(x=>x.id===studio.id):commercial.contracts.find(x=>x.id===studio.id),p=data.find(x=>x.id===studio.projectId);$('studioPreview').innerHTML=isQ?quotePaper(o,p):contractPaper(o,p)}
function quotePaper(q,p){let t=quoteTotal(q),lines=(q.lines||[]).filter(l=>l.included!==false),bilingual=q.language==='bilingual';return '<div class="paper" dir="'+(q.language==='en'?'ltr':'rtl')+'"><div class="paperHeader"><div><div class="paperBrand">RONIX <span>STEEL</span></div><small>Engineering Design • Steel Detailing • BIM Solutions</small></div><div><b>QUOTATION / عرض سعر</b><br>'+q.number+' · R'+q.revision+'<br>'+q.date+'</div></div><h2>Client & Project / العميل والمشروع</h2><table><tr><th>Client</th><td>'+q.client+'</td><th>Project</th><td>'+p.name+'</td></tr></table><h2>Scope & Pricing / نطاق الأعمال والأسعار</h2><table><tr><th>#</th><th>Description</th><th>Qty</th><th>Unit</th><th>Unit Price</th><th>Total</th></tr>'+lines.map((l,i)=>'<tr><td>'+(i+1)+'</td><td>'+l.description+'</td><td>'+l.qty+'</td><td>'+l.unit+'</td><td>'+money(l.unitPrice)+'</td><td>'+money((+l.qty||0)*(+l.unitPrice||0)*(1-(+l.discount||0)/100))+'</td></tr>').join('')+'</table><div class="paperTotal"><div><span>Subtotal</span><b>'+money(t.net)+'</b></div><div><span>VAT</span><b>'+money(t.tax)+'</b></div><div class="grand"><span>Grand Total</span><b>'+money(t.total)+'</b></div></div><h2>Commercial Terms / الشروط التجارية</h2><div style="white-space:pre-line;font-size:11px">'+q.terms+'</div><div class="paperFooter"><span>RONIX STEEL</span><span>Page 1 / 2</span></div></div><div class="paper" dir="'+(q.language==='en'?'ltr':'rtl')+'"><div class="paperHeader"><div class="paperBrand">RONIX <span>STEEL</span></div><div>'+q.number+'</div></div><h2>Exclusions / الاستثناءات</h2><div style="white-space:pre-line;font-size:11px">'+q.exclusions+'</div>'+(q.notes?'<h2>Notes / ملاحظات</h2><div style="white-space:pre-line;font-size:11px">'+q.notes+'</div>':'')+'<h2>Validity / صلاحية العرض</h2><p>This quotation is valid for '+q.validity+' days from issue date.</p><div class="signGrid"><div class="signBox">Prepared by / إعداد<br><b>RONIX STEEL</b></div><div class="signBox">Client Approval / اعتماد العميل</div></div><div class="paperFooter"><span>RONIX STEEL</span><span>Page 2 / 2</span></div></div>'}
function contractPaper(c,p){let total=contractTotal(c);return '<div class="paper" dir="rtl"><div class="paperHeader"><div><div class="paperBrand">RONIX <span>STEEL</span></div><small>Engineering Contract</small></div><div><b>عقد خدمات هندسية</b><br>'+c.number+'<br>'+c.contractDate+'</div></div><h2>بيانات الأطراف والمشروع</h2><table><tr><th>العميل</th><td>'+c.client+'</td><th>المشروع</th><td>'+p.name+'</td></tr><tr><th>عرض السعر المرجعي</th><td>'+(commercial.quotes.find(q=>q.id===c.quoteId)?.number||'—')+'</td><th>مدة الأعمال</th><td>'+c.durationDays+' يوم عمل</td></tr></table><h2>نطاق الأعمال</h2><p>'+c.scope+'</p><h2>قيمة العقد</h2><table><tr><th>البند</th><th>القيمة</th></tr>'+c.lines.map(l=>'<tr><td>'+l.description+'</td><td>'+money((+l.qty||0)*(+l.unitPrice||0)*(1-(+l.discount||0)/100))+'</td></tr>').join('')+'<tr><th>إجمالي قيمة العقد</th><th>'+money(total)+'</th></tr></table><h2>جدول الدفعات</h2>'+scheduleHTML(c)+'<div class="paperFooter"><span>RONIX STEEL</span><span>Page 1 / 2</span></div></div><div class="paper" dir="rtl"><div class="paperHeader"><div class="paperBrand">RONIX <span>STEEL</span></div><div>'+c.number+'</div></div><h2>الشروط التجارية والتعاقدية</h2><div style="white-space:pre-line;font-size:11px">'+c.terms+'</div><h2>الاستثناءات</h2><div style="white-space:pre-line;font-size:11px">'+c.exclusions+'</div><h2>البدء والتعديلات</h2><p>تبدأ الأعمال بعد استلام البيانات المطلوبة وتحقيق شرط البدء المتفق عليه. أي تغيير في النطاق أو القيمة أو المدة بعد التفعيل يعالج كتغيير معتمد / Change Order.</p><div class="signGrid"><div class="signBox">الطرف الأول / العميل</div><div class="signBox">الطرف الثاني / RONIX STEEL</div></div><div class="paperFooter"><span>RONIX STEEL</span><span>Page 2 / 2</span></div></div>'}

