/* SOURCE assets/06-actions.a4e1eac084e5.js */
function printStudio(){
  const holder=document.createElement('div'); holder.innerHTML=$('studioPreview').innerHTML; holder.querySelectorAll('img').forEach(img=>{try{img.src=new URL(img.getAttribute('src'),location.href).href}catch(e){}}); const html=holder.innerHTML;
  const w=window.open('','_blank','noopener=no');
  if(!w){toast('Allow pop-ups to print');return}
  const baseHref=location.href;
  const css=[];
  document.querySelectorAll('style').forEach(s=>css.push(s.textContent||''));
  for(const sheet of Array.from(document.styleSheets)){
    try{css.push(Array.from(sheet.cssRules||[]).map(r=>r.cssText).join('\n'))}catch(e){}
  }
  const printCss=`
    @page{size:A4 portrait;margin:0}
    html,body{margin:0!important;padding:0!important;background:#fff!important;-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}
    body{font-family:"Segoe UI",Tahoma,Arial,sans-serif!important}
    .paper,.r3-paper,.contract-paper{width:210mm!important;min-height:297mm!important;height:297mm!important;margin:0 auto!important;padding:13mm 14mm!important;box-sizing:border-box!important;box-shadow:none!important;border:0!important;background:#fff!important;overflow:hidden!important;page-break-after:always!important;break-after:page!important;position:relative!important}
    .paper:last-child,.r3-paper:last-child,.contract-paper:last-child{page-break-after:auto!important;break-after:auto!important}
    .q-header-r3{margin-top:0!important}
    table{page-break-inside:auto!important}
    tr,td,th{page-break-inside:avoid!important;break-inside:avoid!important}
    .r7-paper-clause,.r7-paper-party,.r7-paper-sign,.r7-paper-scope,.r7-section-title{page-break-inside:avoid!important;break-inside:avoid!important}
    .paperFooter{position:absolute!important;left:14mm!important;right:14mm!important;bottom:8mm!important}
    img{max-width:100%;print-color-adjust:exact!important;-webkit-print-color-adjust:exact!important}
    *{scrollbar-width:none!important}
    *::-webkit-scrollbar{display:none!important}
  `;
  w.document.open();
  w.document.write(`<!doctype html><html><head><meta charset="utf-8"><base href="${baseHref}"><title>RONIX Contract Print</title><style>${css.join('\n')}\n${printCss}</style></head><body>${html}<script>window.addEventListener('load',()=>setTimeout(()=>window.print(),500));<\/script></body></html>`);
  w.document.close();
}

