function saveStudio(){let o=studio.type==='quote'?commercial.quotes.find(x=>x.id===studio.id):commercial.contracts.find(x=>x.id===studio.id);if(!o)return toast('Document not found');if(studio.type==='contract'&&Math.abs(scheduleSum(o)-100)>.01)return toast('جدول الدفعات لازم يساوي 100%');syncProjectCommercial(studio.projectId);localStorage.setItem('ronixCommercialV3',JSON.stringify(commercial));save();toast('Saved ✓');renderStudio()}
function approveStudio(){let o=studio.type==='quote'?commercial.quotes.find(x=>x.id===studio.id):commercial.contracts.find(x=>x.id===studio.id);if(!o)return toast('Document not found');if(studio.type==='quote'){o.status='approved';let p=data.find(x=>x.id===o.projectId);if(p)log(p,currentUser,'Quotation approved: '+o.number)}else{if(Math.abs(scheduleSum(o)-100)>.01)return toast('جدول الدفعات لازم يساوي 100%');if(o.status==='draft')o.status='approved';else if(o.status==='approved'){o.status='active';syncProjectCommercial(o.projectId);let p=data.find(x=>x.id===o.projectId);if(p)log(p,currentUser,'Contract signed & active: '+o.number)}}save();renderStudio()}
function convertStudio(){let q=commercial.quotes.find(x=>x.id===studio.id);if(!q||q.status!=='approved')return toast('اعتمد العرض أولًا');let c=commercial.contracts.find(x=>x.quoteId===q.id&&!x.changeOrderDraft&&x.status!=='cancelled');if(!c){c=newContractFromQuote(q);commercial.contracts.push(c)}studio={type:'contract',id:c.id,projectId:q.projectId||''};save();renderStudio()}
