function bind(){document.querySelectorAll('[data-priority]').forEach(x=>x.onchange=()=>{let p=data.find(z=>z.id===x.dataset.priority);if(!p||!canEditProjectPriority(p))return;p.priority=x.value;if(p.stage>=4&&p.stage<6)p.billingPriority=x.value;log(p,currentUser,'تم تغيير أولوية المشروع إلى '+x.value);save()});document.querySelectorAll('[data-sel]').forEach(x=>x.onclick=()=>{sel=x.dataset.sel;render();page('dash')});document.querySelectorAll('[data-next]').forEach(x=>x.onclick=()=>next(x.dataset.next));document.querySelectorAll('[data-start]').forEach(x=>x.onclick=()=>start(x.dataset.start));document.querySelectorAll('[data-engc]').forEach(x=>x.onclick=()=>engc(x.dataset.engc));document.querySelectorAll('[data-claim]').forEach(x=>x.onclick=()=>claim(x.dataset.claim));document.querySelectorAll('[data-pay]').forEach(x=>x.onclick=()=>pay(x.dataset.pay));document.querySelectorAll('[data-submit]').forEach(x=>x.onclick=()=>task(x.dataset.submit,'submitted'));document.querySelectorAll('[data-confirm]').forEach(x=>x.onclick=()=>task(x.dataset.confirm,'confirmed'));document.querySelectorAll('[data-return]').forEach(x=>x.onclick=()=>task(x.dataset.return,'returned'));document.querySelectorAll('[data-resume]').forEach(x=>x.onclick=()=>task(x.dataset.resume,'in_progress'));document.querySelectorAll('.pt').forEach(x=>x.onclick=()=>{document.querySelectorAll('.pt').forEach(y=>y.classList.remove('active'));x.classList.add('active');let q=project(),conf=q.tasks.filter(t=>t.status==='confirmed').length,prog=q.tasks.length?Math.round(q.tasks.reduce((s,t)=>s+t.progress,0)/q.tasks.length):0;$('ptbody').innerHTML=ptBody(q,x.dataset.pt,conf,prog)});document.querySelectorAll('[data-tsapprove]').forEach(x=>x.onclick=()=>{let t=timesheets.find(z=>z.id===x.dataset.tsapprove);if(!t)return;t.status='approved';t.approvedBy=currentUser;let p=data.find(z=>z.id===t.projectId);if(p)log(p,currentUser,'Approved timesheet: '+U(t.user).name+' '+t.hours+'h');save()});document.querySelectorAll('[data-tsreject]').forEach(x=>x.onclick=()=>{let t=timesheets.find(z=>z.id===x.dataset.tsreject);if(!t)return;t.status='rejected';t.approvedBy=currentUser;save()});document.querySelectorAll('[data-tsresubmit]').forEach(x=>x.onclick=()=>{let t=timesheets.find(z=>z.id===x.dataset.tsresubmit);if(!t)return;t.status='pending';save()});document.querySelectorAll('[data-rate]').forEach(x=>x.onchange=()=>{let u=USERS.find(z=>z.id===x.dataset.rate);if(!u)return;u.rate=+x.value||0;save()});document.querySelectorAll('[data-openquote]').forEach(x=>x.onclick=()=>openQuoteStudio(x.dataset.openquote));document.querySelectorAll('[data-opencontract]').forEach(x=>x.onclick=()=>openContractStudio(x.dataset.opencontract))}
function next(id){let p=data.find(x=>x.id===id);if(!p)return;if(p.stage===3&&p.tasks.some(t=>t.status!=='confirmed'))return toast('لا يمكن التحويل: يوجد Tasks غير Confirmed');if(p.stage===3){p.stage=4;p.since='الآن';p.billingPriority=p.priority||'Normal';p.accountsEnteredAt=new Date().toLocaleString('en-GB');log(p,currentUser,'Final Engineering Confirm ✓ — تم تحويل المشروع للحسابات');log(p,'accountant','Ready for Client Contact / Ready for Billing — Priority: '+p.billingPriority);save();return}p.stage=Math.min(6,p.stage+1);p.since='الآن';log(p,currentUser,'انتقل المشروع إلى '+ST[p.stage][0]);save()}

