function start(id){let p=data.find(x=>x.id===id);if(!p.tasks.length)return toast('وزع Task واحدة على الأقل أولًا');p.stage=2;p.since='الآن';log(p,currentUser,'بدأ التنفيذ الهندسي');save()}
function engc(id){let p=data.find(x=>x.id===id);if(!p.tasks.length||p.tasks.some(t=>t.status!=='confirmed'))return toast('لا يمكن: أكد كل Tasks أولًا');p.stage=3;p.since='الآن';log(p,currentUser,'Engineering package ready for final confirmation');save()}
