function claim(id){let p=data.find(x=>x.id===id),c=contractFor(id);if(!c||c.status!=='active')return toast('لا يمكن المطالبة بدون عقد Active');let cv=contractTotal(c),eligible=nextBillable(p);if(eligible<=0)return toast('لا يوجد استحقاق مفتوح حسب جدول الدفعات');let v=Number(prompt('قيمة المطالبة حسب العقد وجدول الدفعات:',eligible));if(!v)return;if(v>eligible+.01)return toast('القيمة أعلى من الاستحقاق الحالي');if((+p.invoice||0)+v>cv+.01)return toast('لا يمكن تجاوز قيمة العقد');p.invoice=(+p.invoice||0)+v;let total=cv,row=(c.schedule||[]).find(x=>(+x.claimed||0)<total*(+x.percent||0)/100-.5);if(row)row.claimed=(+row.claimed||0)+v;p.stage=5;p.since='الآن';log(p,currentUser,'تم إصدار مطالبة '+money(v)+' حسب '+c.number);save()}
function pay(id){let p=data.find(x=>x.id===id),r=p.invoice-p.paid,v=Number(prompt('المبلغ المستلم:',r));if(!v)return;p.paid=Math.min(p.invoice,p.paid+v);log(p,currentUser,'تم استلام دفعة '+money(v));if(p.paid>=p.invoice){p.stage=6;p.since='—';log(p,currentUser,'Financially Closed')}save()}
