// === RONIX MASTER DATA + COST CONTROL EXTENSION ===
const masterSeed={customers:[],vendors:[],vendorBills:[],expenses:[]};
let masters;try{masters=JSON.parse(localStorage.getItem('ronixMastersV31'))||JSON.parse(JSON.stringify(masterSeed))}catch(e){masters=JSON.parse(JSON.stringify(masterSeed))}
function saveMasters(){localStorage.setItem('ronixMastersV31',JSON.stringify(masters))}
function customerByName(n){return masters.customers.find(c=>c.name===n)||null}
function customerProjects(cid){let c=masters.customers.find(x=>x.id===cid);return c?data.filter(p=>p.client===c.name):[]}
function vendorCost(pid){return masters.vendorBills.filter(b=>b.projectId===pid).reduce((a,b)=>a+(+b.amount||0),0)}
function directCost(pid){return masters.expenses.filter(e=>e.projectId===pid).reduce((a,e)=>a+(+e.amount||0),0)}
function totalProjectCost(pid){return projectLaborCost(pid)+vendorCost(pid)+directCost(pid)}
function actualProjectProfit(pid){let p=data.find(x=>x.id===pid);return (+p?.invoice||0)-totalProjectCost(pid)}
