function renderCustomers(){if(!$('customersTable'))return;let rows=masters.customers.map(c=>{let ps=customerProjects(c.id),invoiced=ps.reduce((a,p)=>a+(+p.invoice||0),0),paid=ps.reduce((a,p)=>a+(+p.paid||0),0),cv=ps.reduce((a,p)=>a+contractValue(p.id),0);return `<tr data-customer="${c.id}" class="click"><td><b>${c.id}</b></td><td><b>${c.name}</b><br><span class="muted">${c.phone||''}</span></td><td>${ps.length}</td><td>${money(cv)}</td><td>${money(invoiced)}</td><td>${money(paid)}</td><td>${money(Math.max(0,invoiced-paid))}</td></tr>`}).join('');$('customersTable').innerHTML='<table class="table"><tr><th>Code</th><th>Customer</th><th>Projects</th><th>Contract Value</th><th>Invoiced</th><th>Collected</th><th>Outstanding</th></tr>'+rows+'</table>';if(!$('customerFile').dataset.cid&&masters.customers[0])$('customerFile').dataset.cid=masters.customers[0].id;renderCustomerFile($('customerFile').dataset.cid)}
