  function openCustomerEdit(id){let c=masters.customers.find(x=>x.id===id);if(!c)return;$('customerEditId').value=id;$('ecName').value=c.name||'';$('ecContact').value=c.contactPerson||'';$('ecPhone').value=c.phone||'';$('ecEmail').value=c.email||'';$('ecAddress').value=c.address||'';$('ecTax').value=c.taxNo||'';$('ecCR').value=c.commercialReg||'';$('ecActive').value=String(c.active!==false);$('ecNotes').value=c.notes||'';$('customerEditM').classList.add('show')}
  function saveCustomerEdit(){const id=$('customerEditId').value,c=masters.customers.find(x=>x.id===id);if(!c)return;const n=norm($('ecName').value);if(!n)return toast('اسم العميل مطلوب');if(masters.customers.some(x=>x.id!==id&&low(x.name)===low(n)))return toast('اسم العميل مستخدم بالفعل');const old=c.name;c.name=n;c.contactPerson=norm($('ecContact').value);c.phone=norm($('ecPhone').value);c.email=norm($('ecEmail').value);c.address=norm($('ecAddress').value);c.taxNo=norm($('ecTax').value);c.commercialReg=norm($('ecCR').value);c.active=$('ecActive').value==='true';c.notes=norm($('ecNotes').value);data.forEach(p=>{if(p.customerId===id||low(p.client)===low(old)){p.customerId=id;p.client=n}});commercial.quotes.forEach(q=>{if(q.customerId===id||low(q.client)===low(old)){q.customerId=id;q.client=n}});commercial.contracts.forEach(k=>{if(k.customerId===id||low(k.client)===low(old)){k.customerId=id;k.client=n}});$('customerEditM').classList.remove('show');save();toast('تم تحديث العميل وربطه بكل سجلاته ✓')}
