  function saveVendorBill(){let vendorId=$('vbVendor').value,projectId=$('vbProject').value,amount=Math.round(+$('vbAmount').value||0),paid=Math.round(+$('vbPaid').value||0);if(!vendorId||!masters.vendors.some(v=>v.id===vendorId))return toast('اختر المورد');if(!projectId||!data.some(p=>p.id===projectId))return toast('اختر المشروع');if(amount<=0)return toast('قيمة الفاتورة يجب أن تكون أكبر من صفر');if(paid<0||paid>amount)return toast('المدفوع يجب أن يكون بين صفر وقيمة الفاتورة');if(paid>0)return toast('احفظ الفاتورة أولًا، ثم سجل القبض من دفعات الموردين ليتوثق السند');let b={id:nextId('VB',masters.vendorBills),vendorId,projectId,amount,paid,date:$('vbDate').value,reference:norm($('vbRef').value),notes:norm($('vbNotes').value),status:paid>=amount?'paid':paid>0?'partial':'open'};masters.vendorBills.push(b);let p=data.find(x=>x.id===projectId);if(p)log(p,currentUser,'Vendor bill '+b.id+' linked to '+masters.vendors.find(v=>v.id===vendorId).name+' — '+money(amount));$('vendorBillM').classList.remove('show');save();toast('تم ربط فاتورة المورد بالمشروع ✓')}
