      const pe=e.target.closest('[data-projectexpense]');if(pe){e.stopPropagation();if(canCostEdit())openExpense(pe.dataset.projectexpense);return;}
      const vp=e.target.closest('[data-vendorpay]');if(vp){e.stopPropagation();if(canCostEdit())payVendorBill(vp.dataset.vendorpay);return;}
