/* SOURCE assets/19-r9-direct-print.js */
(function(){
  'use strict';
  function directPrintStudio(){
    const studioEl=document.getElementById('commercialStudio');
    const preview=document.getElementById('studioPreview');
    if(!studioEl || !preview || !preview.querySelector('.paper,.r3-paper,.contract-paper')){
      if(typeof toast==='function') toast('افتح معاينة العقد أولًا / Open contract preview first');
      return;
    }
    document.body.classList.add('ronix-printing');
    // Force layout before invoking the native browser print dialog.
    void preview.offsetHeight;
    try{
      window.focus();
      window.print();
    } finally {
      // Chrome returns after the print dialog is closed. Keep a safety cleanup as well.
      setTimeout(()=>document.body.classList.remove('ronix-printing'), 250);
    }
  }
  window.printStudio=directPrintStudio;
  function wire(){
    const b=document.getElementById('studioPrint');
    if(b && !b.dataset.r9PrintWired){
      b.dataset.r9PrintWired='1';
      b.onclick=null;
      b.addEventListener('click',function(e){
        e.preventDefault();
        e.stopImmediatePropagation();
        directPrintStudio();
      },true);
      b.title='Print current A4 preview directly';
    }
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',wire,{once:true}); else wire();
  window.addEventListener('afterprint',()=>document.body.classList.remove('ronix-printing'));
})();

