    const s=String(ev?.text||'');
    if(moneyRx.test(s)||finRx.test(s))return 'financial';
    if(commercialRx.test(s))return 'commercial';
    if(/task|drawing|engineering|review|checker|submitted|confirmed|returned|priority|health|scope|توزيع|مهمة|رسومات|هندسة|مراجعة|اعتماد|مرتجع|أولوية|صحة\s*المشروع/i.test(s))return 'engineering';
