     sel.innerHTML=rows.map(c=>`<option value="${c.id}">${c.number} — ${c.client} — ${money(cTotal(c))}</option>`).join('')||`<option value="">${t('لا يوجد عقد Active متاح','No eligible Active contract')}</option>`;
