 const contractAmount=c=>typeof contractTotal==='function'?num(contractTotal(c)):num((c?.lines||[]).reduce((s,l)=>s+(Number(l.qty)||0)*(Number(l.unitPrice)||0)*(1-(Number(l.discount)||0)/100),0));
