  if(!c){
   if(typeof newContractFromQuote!=='function')return toast(tr('تعذر إنشاء العقد','Contract creation is unavailable'));
   c=newContractFromQuote(q);commercial.contracts.push(c);
  }
  c.projectId=p.id;c.projectName=c.projectName||p.name;c.customerId=c.customerId||p.customerId||q.customerId||'';
  p.sourceContractId=c.id;p.sourceContractNumber=c.number;p.commercialSourceType='contract';
  addEvent(p,tr('تم إنشاء مسودة العقد من عرض السعر ','Contract draft created from quotation ')+(q.number||q.id));
