 function issueAdvanceClaim(pid){
  if(!canFinance())return toast(tr('إصدار المطالبة متاح للمالك أو المحاسب فقط','Only Owner or Accountant can issue the claim'));
  const p=projectById(pid),info=p&&advanceInfo(p);if(!p||!info?.contract)return toast(tr('أنشئ العقد أولًا','Create the contract first'));
  if(info.contract.status!=='active')return toast(tr('يجب اعتماد العقد وتفعيله أولًا','Approve and activate the contract first'));
  if(!info.row||info.due<=0)return toast(tr('لا توجد دفعة مقدمة في جدول العقد','No advance milestone exists in the contract schedule'));
  if(info.claimed>=info.due)return toast(tr('مطالبة الدفعة المقدمة صادرة بالفعل','The advance claim is already issued'));
  const scheduled=(info.contract.schedule||[]).reduce((sum,row)=>sum+num(row.claimed),0);
  const unallocated=Math.max(0,num(p.invoice)-scheduled),delta=info.due-info.claimed;
  p.invoice=num(p.invoice)+Math.max(0,delta-unallocated);
  info.row.claimed=info.due;info.row.claimId=info.row.claimId||`CLM-${p.id.replace(/[^A-Z0-9]/gi,'')}-${info.row.id||'ADV'}`;
  info.row.claimedAt=now();info.row.claimedBy=currentUser;info.row.status='issued';
  addEvent(p,tr('تم إصدار مطالبة الدفعة المقدمة ','Advance payment claim issued ')+info.row.claimId+' — '+cash(info.due));
  refresh();toast(tr('تم إصدار مطالبة الدفعة المقدمة وربطها بالعقد والمشروع ✓','Advance claim issued and linked to contract and project ✓'));
 }

 function receiveAdvance(pid){
  if(!canFinance())return toast(tr('تسجيل التحصيل متاح للمالك أو المحاسب فقط','Only Owner or Accountant can record collection'));
  const p=projectById(pid),info=p&&advanceInfo(p);if(!p||!info?.row)return toast(tr('لا توجد دفعة مقدمة مسجلة','No advance milestone is registered'));
  if(info.claimed<=0)return toast(tr('أصدر مطالبة الدفعة المقدمة أولًا','Issue the advance claim first'));
  const outstanding=Math.max(0,info.claimed-info.paid);if(!outstanding)return toast(tr('الدفعة المقدمة محصلة بالكامل','Advance payment is fully collected'));
  const amount=num(prompt(tr('قيمة التحصيل','Collection amount')+':',outstanding));
  if(amount<=0||amount>outstanding)return toast(tr('قيمة التحصيل غير صحيحة أو أكبر من المتبقي','Invalid amount or greater than outstanding balance'));
  const reference=String(prompt(tr('مرجع التحويل أو الإيصال','Transfer / receipt reference')+':','')||'').trim();
  info.row.paid=info.paid+amount;info.row.payments=Array.isArray(info.row.payments)?info.row.payments:[];
  info.row.payments.unshift({id:`RCPT-${Date.now()}`,amount,date:today(),reference,createdAt:now(),createdBy:currentUser});
  info.row.status=info.row.paid>=info.due?'paid':'partial';info.row.paidAt=info.row.status==='paid'?now():info.row.paidAt||'';
  p.paid=num(p.paid)+amount;
  addEvent(p,tr('تم تحصيل ','Collected ')+cash(amount)+tr(' من الدفعة المقدمة',' from advance payment')+(reference?' — '+reference:''));
  refresh();toast(info.row.status==='paid'?tr('تم تحصيل الدفعة المقدمة؛ أصبح بدء التنفيذ متاحًا ✓','Advance collected; project start is now unlocked ✓'):tr('تم تسجيل دفعة جزئية، وما زال بدء التنفيذ مقفلاً','Partial payment recorded; project start remains locked'));
 }

