 function receiptRows(p){const list=receipts(p.id).slice().sort((a,b)=>String(b.createdAt||b.date).localeCompare(String(a.createdAt||a.date)));return `<section class="r37-section"><div class="r37-section-title"><b>${tr('سندات قبض المشروع','Project Receipts')}</b><button type="button" class="btn small green" data-r37-receipt="${esc(p.id)}">+ ${tr('دفعة جديدة','New Receipt')}</button></div>${list.length?`<div class="r37-receipt-list">${list.map(r=>`<article class="${r.status==='reversed'?'cancelled':''}"><div><b>${esc(r.id)}</b><span>${esc(r.date||'')} · ${esc(r.reference||'—')}</span></div><span>${esc(r.milestoneLabel||r.milestoneId||tr('غير موزعة','Unallocated'))}</span><strong>${cash(r.amount)}</strong><div>${r.status==='posted'?`<em>${tr('مرحّل','Posted')}</em><button type="button" class="btn small red" data-r37-cancel="${esc(r.id)}" title="${tr('يُنشئ قيدًا عكسيًا ولا يحذف السجل','Posts a reversing entry; does not delete history')}">${tr('إلغاء بسبب خطأ','Cancel Error')}</button>`:`<em class="cancelled">${tr('ملغى بقيد عكسي','Cancelled by reversal')}</em>`}</div></article>`).join('')}</div>`:`<div class="r37-empty">${tr('لا توجد سندات قبض بعد','No receipts yet')}</div>`}</section>`}
