 function inject(){const board=$('r27Board'),p=project(typeof sel!=='undefined'?sel:'');if(!board||!p)return;board.querySelector('.r39-order,.r39-assignment')?.remove();board.insertAdjacentHTML('afterbegin',orderPanel(p));wire()}
 function decorateLists(){document.querySelectorAll('#projectsTable tr,#dashProjects tr').forEach(row=>{const id=(row.textContent||'').match(/PRJ-\d+/)?.[0],p=project(id);if(!p||row.querySelector('.r39-state'))return;const cell=row.cells?.[0]||row.querySelector('td');if(cell)cell.insertAdjacentHTML('beforeend',`<span class="r39-state ${esc(state(p))}">${esc(statusText(p))}</span>`)})}
