function stateText(s){return({todo:tr('لم يبدأ','Not Started'),in_progress:tr('جاهزة للإرسال','Ready to Submit'),submitted:tr('بانتظار اعتماد الـChecker','Waiting Checker'),returned:tr('مرتجعة للمهندس','Returned'),confirmed:tr('معتمدة','Confirmed')})[s]||s||'—'}
function action(p,t){const key=esc(p.id+':'+t.id);if(worker(p,t)&&['todo','in_progress','returned'].includes(t.status)){if(Number(t.progress)===100)return`<button class="btn primary r42-submit" data-submit="${key}">${t.status==='returned'?tr('إعادة إرسال للـChecker','Resubmit to Checker'):tr('إرسال للـChecker','Send to Checker')}</button>`;return`<button class="btn r21-update" data-r21-view="${key}">${tr('تحديث العمل','Update Work')}</button>`}if(checker(p,t)&&t.status==='submitted')return`<button class="btn green r42-confirm" data-confirm="${key}">${tr('اعتماد','Confirm')}</button><button class="btn red r42-return" data-return="${key}">${tr('إرجاع','Return')}</button>`;if(checker(p,t)&&t.status==='confirmed')return`<button class="btn red" data-reopen="${key}">${tr('فتح Revision','Open Revision')}</button>`;return`<button class="btn r21-update" data-r21-view="${key}">${tr('تفاصيل','Details')}</button>`}
function reviewBoard(p){const ts=technical(p);return`<section class="r42-review"><div class="r42-head"><div><small>Checker Gate</small><h3>${tr('اعتماد الأعمال الهندسية','Engineering Approval')}</h3><p>${tr('لا تُحتسب المهمة معتمدة ولا تنتقل للحسابات قبل Confirm.','No task is approved or sent to Accounts before Confirm.')}</p></div><strong>${ts.filter(t=>t.status==='confirmed').length}/${ts.length}</strong></div>${ts.map(t=>`<article><div><small>${esc(['wire','connections'].includes(category(t))?'Modeling':'Fabrication')}</small><b>${esc(t.name)}</b><span>${esc(person(t.assignee))}</span></div><div><small>${tr('إنجاز المهندس','Engineer Work')}</small><b>${Number(t.progress)||0}%</b></div><div><small>${tr('حالة المراجعة','Review Status')}</small><b class="r42-state ${esc(t.status||'todo')}">${esc(stateText(t.status))}</b></div><div class="r42-actions">${action(p,t)}</div></article>`).join('')}</section>`}
