function wire(){normalize();decorateInbox();document.querySelectorAll('[data-submit],[data-confirm],[data-return],[data-reopen]').forEach(b=>{if(b.dataset.r42Bound)return;b.dataset.r42Bound='1';b.onclick=e=>{e.preventDefault();e.stopPropagation();const k=b.dataset.submit||b.dataset.confirm||b.dataset.return||b.dataset.reopen,s=b.dataset.submit?'submitted':b.dataset.confirm?'confirmed':b.dataset.return?'returned':'reopened';window.task(k,s)}})}
