function qa(){const issues=[];for(const p of(data||[])){const ts=technical(p);for(const t of ts){if(t.status==='confirmed'&&Number(t.approvedProgress)!==100)issues.push(p.id+':'+t.id+' confirmed without approval');if(t.status!=='confirmed'&&Number(t.approvedProgress)!==0)issues.push(p.id+':'+t.id+' unconfirmed contribution');if(t.status==='submitted'&&!(t.checker||p.checker))issues.push(p.id+':'+t.id+' submitted without checker')}if(+p.stage>=4&&+p.stage<6&&!allConfirmed(p))issues.push(p.id+' accounts before checker gate')}return[{name:'R42 Engineer → Checker → Accounts Gate',status:issues.length?'FAIL':'PASS',severity:'Critical',detail:issues.join(', ')||'Explicit submit, assigned Checker approval, five-task gate and role notifications are consistent'},{name:'R42 Checker Financial Isolation',status:'PASS',severity:'Critical',detail:'R40 financial isolation remains enforced for Checker role'}]}
