  audit(p,currentUser,'Checker Approved: '+t.name);notify(p,t.assignee,'task_confirmed',tr('تم اعتماد المهمة: ','Task approved: ')+t.name);notify(p,p.pm||'pm','task_confirmed',tr('اعتمد الـChecker المهمة: ','Checker approved: ')+t.name);
  const ready=markReady(p);return save(ready?tr('تم اعتماد المهمة. جميع البنود جاهزة الآن للاعتماد الفني النهائي من الـChecker.','Task approved. All tasks are now ready for the Checker final technical approval.'):tr('تم اعتماد المهمة.','Task approved.'));
